// The fixture client: serves web/fixtures (API-shaped JSON generated by the real
// simulation engine, see internal/devtools/fixtures) through the same typed
// interface as the real client. Files are read through the /fixture-data route.
//
// Layout:
//   ontologies.json
//   <ont>/detail.json, document.json, graph.json, revisions.json,
//         validation.json, test-report.json, plan.<flow>.json,
//         runs/<scenario>.json
//   optional, per revision N: document.rN.json, graph.rN.json, plan.<flow>.rN.json
//         (a numeric ?rev= reads these, falling back to the unsuffixed file)
//   optional: commits.json (an api.CommitList)
//
// Local stores (§16.6, internal/api/local.go), outside any ontology:
//   compose/runs.json (an api.ComposeRunList)
//   compose/<task>/run.json (an api.ComposeRunDetail), compose/<tree root>/tree.json,
//   compose/<task>/artifacts/<key>.json
//   replays.json (an api.ReplayList)
//   optional: replays/<name>.<ontology>.run.json (an api.ReplayRun, the recorded replay)
//
// Ontologies listed in EXTRA_ONTOLOGIES are hand-made (web/fixtures/commits-demo)
// or generated separately; they are added to ontologies.json when present.
// Diffs, impact and commit details are computed here from the revision
// documents and plans (src/lib/model/impact.ts).

import { ApiError, FixtureUnsupportedError, type MosaicClient } from "./client";
import type { Evidence, StoredTestReport } from "./types";
import { diffDocuments, impactOf } from "@/lib/model/impact";
import { normalizeCommits, normalizeGraph, normalizeReport, normalizeRun, normalizeValidation } from "./normalize";
import type {
  Change,
  CommitDetail,
  CommitList,
  ComposeRunDetail,
  ComposeRunList,
  ComposeTree,
  Diff,
  Document,
  Graph,
  Health,
  Impact,
  JsonValue,
  OntologyDetail,
  OntologyList,
  Plan,
  ReplayFilter,
  ReplayList,
  ReplayRun,
  RevisionList,
  RevSelector,
  RunList,
  SimulationRequest,
  SimulationRun,
  SourceFile,
  SystemUpdate,
  SystemVersion,
  TestReport,
  Validation,
} from "./types";

const RUN_PREFIX = "run_fixture_";

/** Fixture ontologies outside ontologies.json, listed when their detail.json exists. */
const EXTRA_ONTOLOGIES = ["commits-demo", "shop", "engine-logic"];

const isNum = (rev?: RevSelector) => !!rev && /^\d+$/.test(rev);
const is404 = (err: unknown) => err instanceof ApiError && err.status === 404;

/** Lists the request fields that override a scenario (anything but flow/scenario/rev/save). */
export function requestOverrides(req: SimulationRequest): string[] {
  const out: string[] = [];
  if (req.seed !== undefined) out.push("seed");
  if (req.input !== undefined) out.push("input");
  if (req.choices && Object.keys(req.choices).length) out.push("choices");
  if (req.state && Object.keys(req.state).length) out.push("state");
  if (req.faults && req.faults.length) out.push("faults");
  if (req.expect && req.expect.length) out.push("expectations");
  if (req.fixtures && req.fixtures.length) out.push("fixtures");
  if (req.topology && Object.keys(req.topology).length) out.push("topology");
  if (req.config && Object.keys(req.config).length) out.push("config");
  if (req.clock && (req.clock.epoch || req.clock.epoch_ms)) out.push("clock");
  if (req.resolution && Object.keys(req.resolution).length) out.push("resolution");
  return out;
}

export class FixtureClient implements MosaicClient {
  readonly mode = "fixtures" as const;
  readonly target = "web/fixtures";
  private readonly base: string;
  private readonly cache = new Map<string, Promise<unknown>>();
  /** Replay files removed this session (fixtures are read-only, so removal is in memory). */
  private readonly removedReplays = new Set<string>();

  constructor(base = "/fixture-data") {
    this.base = base;
  }

  private load<T>(path: string): Promise<T> {
    let p = this.cache.get(path) as Promise<T> | undefined;
    if (!p) {
      p = fetch(`${this.base}/${path}`).then(async (res) => {
        if (!res.ok) {
          throw new ApiError(res.status === 404 ? 404 : res.status, {
            code: res.status === 404 ? "not_found" : "internal",
            message: res.status === 404 ? `no fixture at web/fixtures/${path}` : `fixture read failed (${res.status})`,
          });
        }
        return (await res.json()) as T;
      });
      p.catch(() => this.cache.delete(path));
      this.cache.set(path, p);
    }
    // Hand out copies so callers can never mutate the cached value.
    return p.then((v) => structuredClone(v));
  }

  async health(): Promise<Health> {
    return { status: "ok", version: "fixtures", dolt: "none" };
  }

  async systemVersion(): Promise<SystemVersion> {
    return {
      version: "fixtures",
      commit: "",
      dirty: false,
      branch: "",
      upstream: "",
      source_dir: "",
      update: { available: false, reason: "not available: fixtures mode", behind: 0, ahead: 0, latest_commit: "", latest_subject: "", checked_at: null },
    };
  }

  async systemUpdate(): Promise<SystemUpdate> {
    throw new FixtureUnsupportedError("not available: fixtures mode");
  }

  async getSource(): Promise<SourceFile> {
    throw new FixtureUnsupportedError("Source files are not available in fixtures mode; the viewer fetches them through a live mosaicd.");
  }

  async listOntologies(): Promise<OntologyList> {
    const base = await this.load<OntologyList>("ontologies.json");
    const extra = await Promise.all(
      EXTRA_ONTOLOGIES.filter((id) => !base.ontologies.some((o) => o.id === id)).map((id) =>
        this.load<OntologyDetail>(`${id}/detail.json`).then(
          ({ counts: _counts, draft_dirty: _dirty, ...summary }) => {
            void _counts;
            void _dirty;
            return summary;
          },
          () => null,
        ),
      ),
    );
    return { ontologies: [...base.ontologies, ...extra.filter((o) => o !== null)] };
  }

  getOntology(id: string) {
    return this.load<OntologyDetail>(`${id}/detail.json`);
  }

  /** `<id>/<name>.r<N>.json` for a numeric revision when it exists, else `<id>/<name>.json`. */
  private async loadRev<T>(id: string, name: string, rev?: RevSelector): Promise<T> {
    if (isNum(rev)) {
      try {
        return await this.load<T>(`${id}/${name}.r${rev}.json`);
      } catch (err) {
        if (!is404(err)) throw err;
      }
    }
    return this.load<T>(`${id}/${name}.json`);
  }

  getDocument(id: string, rev?: RevSelector) {
    return this.loadRev<Document>(id, "document", rev);
  }

  async getGraph(id: string, rev?: RevSelector): Promise<Graph> {
    return normalizeGraph(await this.loadRev<Graph>(id, "graph", rev));
  }

  listRevisions(id: string) {
    return this.load<RevisionList>(`${id}/revisions.json`);
  }

  /** "latest" and "draft" read the unsuffixed files (the fixtures' drafts are clean). */
  async diff(id: string, from?: RevSelector, to?: RevSelector): Promise<Diff> {
    const f = from || "latest";
    const t = to || "draft";
    return { from: f, to: t, changes: await this.changes(id, f, t) };
  }

  private async changes(id: string, from: RevSelector, to: RevSelector): Promise<Change[]> {
    const norm = (r: RevSelector) => (isNum(r) ? r : r === "base" ? "0" : "latest");
    if (norm(from) === norm(to)) {
      await this.getOntology(id);
      return [];
    }
    const doc = (r: RevSelector) => (norm(r) === "0" ? undefined : this.getDocument(id, r));
    const [a, b] = await Promise.all([doc(from), doc(to)]);
    return diffDocuments(a, b);
  }

  async impact(id: string, from: RevSelector, to: RevSelector): Promise<Impact> {
    const changes = await this.changes(id, from, to);
    // "base" (and 0) is the empty document before the first revision.
    const revs = [from, to].filter((r) => r !== "0" && r !== "base");
    const docs = await Promise.all(revs.map((r) => this.getDocument(id, r)));
    const plans = new Map<string, Plan[]>();
    await Promise.all(
      docs.flatMap((d, i) =>
        d.flows.map(async (fl) => {
          const p = await this.getPlan(id, fl.id, revs[i]).catch(() => null);
          if (!p) return;
          if (!plans.has(fl.id)) plans.set(fl.id, []);
          plans.get(fl.id)!.push(p);
        }),
      ),
    );
    return impactOf(changes, plans);
  }

  async listCommits(id: string): Promise<CommitList> {
    try {
      return normalizeCommits(await this.load<CommitList>(`${id}/commits.json`));
    } catch (err) {
      if (!is404(err)) throw err;
      await this.getOntology(id);
      return { repo: "", commits: [] };
    }
  }

  async getCommit(id: string, sha: string): Promise<CommitDetail> {
    const { commits } = await this.listCommits(id);
    // Like mosaicd: a full sha or a unique prefix of at least 7 characters.
    if (sha.length < 7) throw new ApiError(400, { code: "bad_request", message: `commit sha ${sha} is shorter than 7 characters` });
    const hits = commits.filter((c) => c.sha.startsWith(sha));
    if (hits.length > 1) throw new ApiError(409, { code: "conflict", message: `commit prefix ${sha} is ambiguous` });
    const idx = hits.length ? commits.indexOf(hits[0]) : -1;
    if (idx < 0) throw new ApiError(404, { code: "not_found", message: `unknown commit ${sha}` });
    const commit = commits[idx];
    const after = commit.revision ?? 0;
    // The revision modelling the parent, or the latest earlier one.
    const parent = commits.find((c) => c.sha === commit.parent && c.revision);
    let before = parent?.revision ?? 0;
    if (!before) for (const c of commits.slice(0, idx)) if (c.revision && c.revision < (after || Infinity)) before = Math.max(before, c.revision);
    if (!after) return { commit, before, after, changes: [], impact: null };
    const from = before ? String(before) : "base";
    const [changes, impact] = await Promise.all([this.changes(id, from, String(after)), this.impact(id, from, String(after))]);
    return { commit, before, after, changes, impact };
  }

  async validate(id: string, rev?: RevSelector): Promise<Validation> {
    const v = normalizeValidation(await this.load<Validation>(`${id}/validation.json`));
    return { ...v, revision: rev || v.revision };
  }

  getPlan(id: string, flow: string, rev?: RevSelector) {
    return this.loadRev<Plan>(id, `plan.${flow}`, rev);
  }

  async listRuns(id: string, limit?: number): Promise<RunList> {
    const doc = await this.getDocument(id);
    const runs = await Promise.all(
      doc.scenarios.map((s) =>
        this.load<SimulationRun>(`${id}/runs/${s.id}.json`)
          .then((r) => {
            const { trace: _trace, ...rest } = normalizeRun(r);
            void _trace;
            return rest as SimulationRun;
          })
          .catch(() => null),
      ),
    );
    const list = runs.filter((r): r is SimulationRun => r !== null).sort((a, b) => b.created_at.localeCompare(a.created_at));
    return { runs: limit ? list.slice(0, limit) : list };
  }

  async runSimulation(id: string, req: SimulationRequest): Promise<SimulationRun> {
    if (!req.scenario) {
      throw new FixtureUnsupportedError(
        "Fixture mode can only replay recorded scenario runs. Ad hoc flow runs need a live mosaicd.",
      );
    }
    const overrides = requestOverrides(req);
    if (overrides.length) {
      throw new FixtureUnsupportedError(
        `Fixture mode replays the recorded run of "${req.scenario}" only; overrides (${overrides.join(", ")}) need a live mosaicd.`,
      );
    }
    return normalizeRun(await this.load<SimulationRun>(`${id}/runs/${req.scenario}.json`));
  }

  async getRun(runId: string): Promise<SimulationRun> {
    if (!runId.startsWith(RUN_PREFIX)) {
      throw new ApiError(404, { code: "not_found", message: `run ${runId} is not a fixture run` });
    }
    const scenario = runId.slice(RUN_PREFIX.length);
    const { ontologies } = await this.listOntologies();
    for (const o of ontologies) {
      try {
        return normalizeRun(await this.load<SimulationRun>(`${o.id}/runs/${scenario}.json`));
      } catch (err) {
        if (!(err instanceof ApiError) || err.status !== 404) throw err;
      }
    }
    throw new ApiError(404, { code: "not_found", message: `unknown run ${runId}` });
  }

  async runTests(id: string, _rev?: RevSelector): Promise<TestReport> {
    void _rev;
    return normalizeReport(await this.load<TestReport>(`${id}/test-report.json`));
  }

  /** Fixtures keep no recorded report. */
  async getTestResults(id: string, _rev?: RevSelector): Promise<StoredTestReport> {
    void _rev;
    throw new ApiError(404, { code: "not_found", message: `no recorded test report for ${id}` });
  }

  /** `<ont>/evidence.json` when a fixture has one; otherwise a 404, shown as "Not benchmarked". */
  async getEvidence(id: string, _rev?: RevSelector): Promise<Evidence> {
    void _rev;
    return this.load<Evidence>(`${id}/evidence.json`);
  }

  async listComposeRuns(): Promise<ComposeRunList> {
    try {
      return await this.load<ComposeRunList>("compose/runs.json");
    } catch (err) {
      if (!is404(err)) throw err;
      return { root: ".mosaic/compose/runs", runs: [] };
    }
  }

  async getComposeTree(task: string): Promise<ComposeTree> {
    const { runs } = await this.listComposeRuns();
    const run = runs.find((r) => r.id === task);
    if (!run) throw new ApiError(404, { code: "not_found", message: `unknown compose task ${task}` });
    return this.load<ComposeTree>(`compose/${run.tree_root}/tree.json`);
  }

  getComposeRun(task: string) {
    return this.load<ComposeRunDetail>(`compose/${task}/run.json`);
  }

  getComposeArtifact(task: string, key: string) {
    return this.load<JsonValue>(`compose/${task}/artifacts/${key}.json`);
  }

  /** replays.json, less the ones removed this session; with `ontology`, only its scenarios' at `rev`. */
  async listReplays(filter?: ReplayFilter): Promise<ReplayList> {
    let l: ReplayList;
    try {
      l = await this.load<ReplayList>("replays.json");
    } catch (err) {
      if (!is404(err)) throw err;
      l = { dir: ".mosaic/replay", replays: [] };
    }
    const replays = l.replays.filter((r) => !this.removedReplays.has(r.name));
    if (!filter?.ontology) return { ...l, replays };
    const doc = await this.getDocument(filter.ontology, filter.rev);
    const ids = new Set(doc.scenarios.map((s) => s.id));
    return { ...l, ontology: filter.ontology, revision: filter.rev || "draft", replays: replays.filter((r) => ids.has(r.scenario)) };
  }

  async deleteReplay(name: string): Promise<void> {
    const { replays } = await this.listReplays();
    if (!replays.some((r) => r.name === name)) throw new ApiError(404, { code: "not_found", message: `no replay ${name} in .mosaic/replay` });
    this.removedReplays.add(name);
  }

  /** Serves the recorded replay run when there is one. */
  async runReplay(id: string, name: string, _rev?: RevSelector): Promise<ReplayRun> {
    void _rev;
    try {
      const r = await this.load<ReplayRun>(`replays/${name}.${id}.run.json`);
      return { ...r, run: normalizeRun(r.run) };
    } catch (err) {
      if (!is404(err)) throw err;
      throw new FixtureUnsupportedError(`Fixture mode has no recorded replay of ${name} against ${id}; replaying needs a live mosaicd.`);
    }
  }
}
